package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;

/**
 * A claim a person has on a sheet. {@code id} is null until the claim is first saved; {@code number}
 * is null unless the claim has been opened (a draft has none; a voided claim keeps it). {@code due} is the
 * due fixed when the claim was settled, or null while it is live (not settled, or settled with no rate).
 * {@code openedBy} is the user who opened the claim, or null while it is a draft. {@code stated} is whether
 * its person's last statement bound it to a figure, {@code statedDue} (null: n/a) — it then shows and totals
 * that figure, not its live one. {@code number} is sheet-wide (1, 2, ...) or, under period numbering,
 * within its period (P1-1, X-1). {@code corrects} is, for a correction, the number of the claim it corrects (null:
 * not a correction). {@code dueBy} is fixed when the claim is created: its date plus its person's own terms, else
 * those of their grade, else the sheet's, each in force on that date; it does not change when the terms or its date change later. While PENDING the claim is not bound: it shows and totals its live figure, and is bound again
 * once rejected (back to OPEN) when the statement included it. {@code deferredUntil} is the date an OPEN claim is
 * deferred until (null: never deferred): while the sheet's today is before it the claim is {@link #deferred deferred}.
 * {@code proofs} is how many proofs the claim has been given. {@code splitFrom} is the number of the claim it was split
 * off (null: not split off another claim).
 */
public record Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
        String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs, String splitFrom) {

    /** A claim not split off another claim. */
    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
            String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs) {
        this(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue, corrects,
                dueBy, deferredUntil, proofs, null);
    }

    /** A claim with no proofs. */
    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
            String corrects, LocalDate dueBy, LocalDate deferredUntil) {
        this(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue, corrects,
                dueBy, deferredUntil, 0);
    }

    /** A claim never deferred. */
    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal due, String openedBy, boolean stated, BigDecimal statedDue,
            String corrects, LocalDate dueBy) {
        this(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue, corrects,
                dueBy, null);
    }

    /** The same claim with another status, number, fixed due and opener. */
    public Claim withStatus(ClaimStatus next, String nextNumber, BigDecimal nextDue, String nextOpenedBy) {
        return new Claim(id, sheetId, personId, amount, date, note, next, nextNumber, nextDue, nextOpenedBy, stated,
                statedDue, corrects, dueBy, deferredUntil, proofs, splitFrom);
    }

    /** The same claim as an open claim bound by no statement: live, with no fixed due. */
    public Claim asOpenUnbound() {
        return new Claim(id, sheetId, personId, amount, date, note, ClaimStatus.OPEN, number, null, openedBy, false,
                null, corrects, dueBy, deferredUntil, proofs, splitFrom);
    }

    /**
     * The claim keeping the rest of its amount once the split amount goes to a new claim: it loses any figure a
     * statement bound it to.
     */
    public Claim splitKeeping(BigDecimal rest) {
        return new Claim(id, sheetId, personId, rest, date, note, status, number, due, openedBy, false, null,
                corrects, dueBy, deferredUntil, proofs, splitFrom);
    }

    /** Whether the claim is a correction: a negative amount naming the settled claim it corrects. */
    public boolean correction() {
        return corrects != null;
    }

    /** Whether the claim counts toward the totals: only OPEN, PENDING and SETTLED claims do. */
    public boolean counts() {
        return status.open() || status == ClaimStatus.SETTLED;
    }

    /** Whether the claim counts toward the live totals when a hold on its person covers it or not: a held open (or pending) claim does not. */
    public boolean counts(boolean held) {
        return status == ClaimStatus.SETTLED || (status.open() && !held);
    }

    /**
     * Whether the claim is deferred on the given today: OPEN, deferred until a date after that day. A deferred claim
     * counts in no total, is not overdue, cannot be settled and is left unbound by a statement.
     */
    public boolean deferred(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }

    /** The same claim deferred until the date. */
    public Claim deferTo(LocalDate until) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue,
                corrects, dueBy, until, proofs, splitFrom);
    }

    /** The same claim on another date with the given number, keeping its due-by and any statement figure. */
    public Claim redateTo(LocalDate nextDate, String nextNumber) {
        return new Claim(id, sheetId, personId, amount, nextDate, note, status, nextNumber, due, openedBy, stated,
                statedDue, corrects, dueBy, deferredUntil, proofs, splitFrom);
    }

    /** The same claim with one more proof. */
    public Claim withProof() {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, due, openedBy, stated, statedDue,
                corrects, dueBy, deferredUntil, proofs + 1, splitFrom);
    }

    /** Whether a proof can be added to the claim: it is neither SETTLED nor VOID. */
    public boolean takesProof() {
        return status != ClaimStatus.SETTLED && status != ClaimStatus.VOID;
    }

    /** Whether the claim is overdue on the given today: OPEN (or PENDING), not deferred, with its due-by before that day. */
    public boolean overdue(LocalDate today) {
        return status.open() && !deferred(today) && dueBy != null && today != null && dueBy.isBefore(today);
    }

    /** Whether a statement binds the claim now: it was stated and is not PENDING. */
    public boolean bound() {
        return stated && status != ClaimStatus.PENDING;
    }

    /** Whether the claim keeps a figure whatever the rates: fixed when settled, or bound by a statement. */
    public boolean keepsFigure() {
        return due != null || (bound() && statedDue != null);
    }

    /**
     * The claim's figure (null: n/a): the due fixed when it was settled, else the figure its statement bound
     * it to (not while PENDING), else its amount at the given live rate (null: none) — no floor. Its live figure
     * rounds by the sheet's policy date.
     */
    public BigDecimal figure(BigDecimal liveRate, Rounding rounding) {
        if (due != null) {
            return due;
        }
        if (bound()) {
            return statedDue;
        }
        return due(amount, liveRate, rounding.modeFor(this));
    }

    /**
     * The claim's due (null: n/a): the due fixed when it was settled, else the greater of the floor in force on its
     * date and its {@link #figure figure} plus the late charge on that figure while it is overdue. A settled claim's
     * fixed due already has the charge and floor frozen in; a correction has no floor and no charge.
     */
    public BigDecimal due(BigDecimal liveRate, BigDecimal floor, LateCharge late, Rounding rounding) {
        BigDecimal figure = figure(liveRate, rounding);
        if (due != null || figure == null || correction()) {
            return figure;
        }
        return atLeast(figure.add(late.on(this, figure, rounding.modeFor(this))), floor);
    }

    /** An amount times a percent rate, divided by 100, rounded by the mode to two decimals; null with no rate. */
    public static BigDecimal due(BigDecimal amount, BigDecimal rate, RoundingMode mode) {
        return rate == null ? null : amount.multiply(rate).movePointLeft(2).setScale(2, mode);
    }

    /** The value raised to the floor (null: no floor). */
    static BigDecimal atLeast(BigDecimal value, BigDecimal floor) {
        return floor == null || value.compareTo(floor) >= 0 ? value : floor.setScale(2);
    }

    /** The audit field for the claim's number, " number=<n>", or "" when it has none. */
    public static String auditNumber(String number) {
        return number == null ? "" : " number=" + number;
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLogLine;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;

/**
 * A period of a sheet: its name (unique on the sheet) and its from and to dates, both inclusive. A closed
 * period keeps the due-total fixed when it was closed ({@code closedTotal}; null while open) and each person's
 * due-total for it then ({@code personTotals}, by person id; empty while open). A soft-closed period
 * ({@code softClosed}; never also {@code closed}) keeps its figures fixed the same way, but claims dated in it can
 * still be added and changed.
 */
public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
        BigDecimal closedTotal, Map<Long, BigDecimal> personTotals, boolean softClosed) {

    /** A new, open period. */
    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this(sheetId, name, from, to, false, null, Map.of(), false);
    }

    /** Whether the period's figures are fixed: it is closed or soft-closed. */
    public boolean fixed() {
        return closed || softClosed;
    }

    /** Whether the period shares a day with the other. */
    public boolean overlaps(Period other) {
        return !from.isAfter(other.to()) && !other.from().isAfter(to);
    }

    /** Whether the date falls in the period, both ends included. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }

    /**
     * The status the claim had at the end of the period's last day, as its status log (oldest first) records it: the
     * last line logged on or before it; null when it was added after. A claim with no log is taken at its status now.
     */
    public ClaimStatus statusAtEnd(Claim claim, List<ClaimLogLine> log) {
        if (log.isEmpty()) {
            return claim.status();
        }
        ClaimStatus status = null;
        for (ClaimLogLine line : log) {
            if (!line.date().isAfter(to)) {
                status = line.status();
            }
        }
        return status;
    }

    /**
     * Whether the claim counts toward the period: dated in it and OPEN, PENDING or SETTLED at the period's end, left
     * out as the live rules say while it is deferred on today, or when it was open then, is open still, a hold of its
     * person covers it (or their retirement date is reached) and no statement binds it (a hold leaves out only open
     * claims). A settled claim voided since leaves it.
     */
    public boolean counts(Claim claim, List<ClaimLogLine> log, Person person, LocalDate today) {
        if (!contains(claim.date())) {
            return false;
        }
        ClaimStatus then = statusAtEnd(claim, log);
        if (then == ClaimStatus.SETTLED) {
            return claim.status() != ClaimStatus.VOID;
        }
        if (then == null || !then.open() || claim.deferred(today)) {
            return false;
        }
        return !claim.status().open() || claim.bound() || !person.heldOn(claim.date(), today);
    }

    /** The same period, closed with its due-total and each person's due-total fixed. */
    public Period close(BigDecimal total, Map<Long, BigDecimal> perPerson) {
        return new Period(sheetId, name, from, to, true, total, Map.copyOf(perPerson), false);
    }

    /** The same period, soft-closed with its due-total and each person's due-total fixed. */
    public Period softClose(BigDecimal total, Map<Long, BigDecimal> perPerson) {
        return new Period(sheetId, name, from, to, false, total, Map.copyOf(perPerson), true);
    }

    /** The same period with these fixed per-person due-totals. */
    public Period withPersonTotals(Map<Long, BigDecimal> perPerson) {
        return new Period(sheetId, name, from, to, closed, closedTotal, Map.copyOf(perPerson), softClosed);
    }

    /** The same period, open again with its due-total live. */
    public Period reopen() {
        return new Period(sheetId, name, from, to, false, null, Map.of(), false);
    }
}
package net.officefloor.hq.app.period;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.math.BigDecimal;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class PeriodRepository {

    private static final String COLUMNS = "sheet_id, name, from_date, to_date, closed, closed_total, soft_closed";

    private final JdbcTemplate jdbc;

    public PeriodRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's periods, earliest first. */
    public List<Period> findAll(String sheetId) {
        List<Period> periods = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? ORDER BY from_date",
                PeriodRepository::map, sheetId);
        Map<String, Map<Long, BigDecimal>> totals = new HashMap<>();
        jdbc.query("SELECT period_name, person_id, total FROM period_person_total WHERE sheet_id = ?",
                (rs) -> {
                    totals.computeIfAbsent(rs.getString("period_name"), (k) -> new HashMap<>())
                            .put(rs.getLong("person_id"), rs.getBigDecimal("total"));
                }, sheetId);
        return periods.stream().map((p) -> p.withPersonTotals(totals.getOrDefault(p.name(), Map.of()))).toList();
    }

    /** The sheet's period with this name, or null. */
    public Period find(String sheetId, String name) {
        List<Period> found = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? AND name = ?",
                PeriodRepository::map, sheetId, name);
        if (found.isEmpty()) {
            return null;
        }
        Map<Long, BigDecimal> totals = new HashMap<>();
        jdbc.query("SELECT person_id, total FROM period_person_total WHERE sheet_id = ? AND period_name = ?",
                (rs) -> {
                    totals.put(rs.getLong("person_id"), rs.getBigDecimal("total"));
                }, sheetId, found.get(0).name());
        return found.get(0).withPersonTotals(totals);
    }

    /** The sheet's closed period containing the date, or null. */
    public Period closedOn(String sheetId, LocalDate date) {
        return findAll(sheetId).stream().filter((p) -> p.closed() && p.contains(date)).findFirst().orElse(null);
    }

    /** The sheet's soft-closed period containing the date, or null. */
    public Period softClosedOn(String sheetId, LocalDate date) {
        return findAll(sheetId).stream().filter((p) -> p.softClosed() && p.contains(date)).findFirst().orElse(null);
    }

    public void insert(Period period) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)",
                period.sheetId(), period.name(), period.from(), period.to());
    }

    /** Store the period's closed and soft-closed flags, fixed due-total (null when reopened) and fixed per-person due-totals. */
    public void saveClosed(Period period) {
        jdbc.update("UPDATE period SET closed = ?, closed_total = ?, soft_closed = ? WHERE sheet_id = ? AND name = ?",
                period.closed(), period.closedTotal(), period.softClosed(), period.sheetId(), period.name());
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?",
                period.sheetId(), period.name());
        period.personTotals().forEach((personId, total) -> jdbc.update(
                "INSERT INTO period_person_total (sheet_id, period_name, person_id, total) VALUES (?, ?, ?, ?)",
                period.sheetId(), period.name(), personId, total));
    }

    private static Period map(ResultSet rs, int n) throws SQLException {
        return new Period(rs.getString("sheet_id"), rs.getString("name"), rs.getObject("from_date", LocalDate.class),
                rs.getObject("to_date", LocalDate.class), rs.getBoolean("closed"), rs.getBigDecimal("closed_total"), Map.of(),
                rs.getBoolean("soft_closed"));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.plugin.variable.Val;

/** Refuses (400) any change to a claim dated inside a closed period. */
public class CheckClaimPeriodOpen {
    public void check(@Val Claim claim, PeriodRepository periods) throws InvalidClaimException {
        Period closed = periods.closedOn(claim.sheetId(), claim.date());
        if (closed != null) {
            throw new InvalidClaimException("The claim is dated in the closed period " + closed.name() + ".");
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Refuses (400) a claim added or edited to a date (blank: the sheet's entry date, else its today) inside a closed period. */
public class CheckClaimInputPeriodOpen {
    public void check(@Val ClaimInput input, @PathVariable("sheetId") String sheetId, SheetRepository sheets,
            PeriodRepository periods) throws InvalidClaimException {
        LocalDate date = input.date() != null ? input.date() : sheets.entryDate(sheetId);
        Period closed = periods.closedOn(sheetId, date);
        if (closed != null) {
            throw new InvalidClaimException("The date " + date + " is in the closed period " + closed.name() + ".");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import org.springframework.stereotype.Component;

/**
 * Marks a claim just added a late entry when the period containing its date is soft-closed, recorded as LATE_ENTRY
 * (after its CLAIM_ADDED); nothing otherwise. Used by the claim form, the quick-add and the paste.
 */
@Component
public class LateEntries {

    private final PeriodRepository periods;
    private final ClaimRepository claims;
    private final Audit audit;

    public LateEntries(PeriodRepository periods, ClaimRepository claims, Audit audit) {
        this.periods = periods;
        this.claims = claims;
        this.audit = audit;
    }

    public void mark(Claim claim, Person person, String user) {
        if (periods.softClosedOn(claim.sheetId(), claim.date()) == null) {
            return;
        }
        claims.markLateEntry(claim);
        audit.record("LATE_ENTRY sheet=" + claim.sheetId() + " by=" + user + " person=" + person.name()
                + " amount=" + claim.amount().setScale(2).toPlainString() + " date=" + claim.date());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Marks the claim just added a late entry when its period is soft-closed (see {@link LateEntries}). */
public class MarkLateEntry {
    public void mark(@Val Claim claim, @Val Person person, @RequestParam("user") String user, LateEntries lateEntries) {
        lateEntries.mark(claim, person, user);
    }
}
