            if (settledOn == null || sheets.today(claim.sheetId()).isAfter(settledOn.plusDays(VOID_SETTLED_DAYS))) {
                throw new InvalidClaimException("A settled claim can be voided only within " + VOID_SETTLED_DAYS
                        + " days of its settlement.");
            }
        }
        if (found == ClaimAction.REJECT && request.reason().isEmpty()) {
            throw new InvalidClaimException("A reason is required to reject a claim.");
        }
        BigDecimal due = found.settles() ? settledDue(found == ClaimAction.RESETTLE ? claim.asOpenUnbound() : claim, sheets, people, rates, settings, claims) : claim.due();
        if (found == ClaimAction.OPEN && (claim.note() == null || claim.note().isBlank())
                && settings.dated(claim.sheetId()).needsNote(claim.date(),
                        ClaimDueNow.of(claim, sheets, people, rates, settings, claims))) {
            throw new InvalidClaimException("The claim's due is above the note threshold: it needs a note to be opened.");
        }
        if ((found == ClaimAction.SETTLE || found == ClaimAction.APPROVE) && claim.proofs() == 0
                && settings.dated(claim.sheetId()).needsProof(claim.date(), due)) {
            throw new InvalidClaimException("The claim's due is above the proof threshold: it needs a proof to be "
                    + (found == ClaimAction.SETTLE ? "settled" : "approved") + ".");
        }
        if (found == ClaimAction.SETTLE && !settings.find(claim.sheetId()).maySettle(user, due)) {
            found = ClaimAction.PEND;
            due = null;
        }
        String next = switch (found) {
            case OPEN -> nextNumber(claim, sheets, settings, periods);
            default -> claim.number();
        };
        applied.set(found);
        previous.set(new PreviousDue(claim.due(), claim.status() == ClaimStatus.SETTLED));
        number.set(new ClaimNumber(next));
        updated.set(claim.withStatus(found.to(), next, due, found == ClaimAction.OPEN ? user : claim.openedBy()));
    }

    /** The number opening the claim gives it now: the sheet's next, or the next within its period under period numbering. */
    static String nextNumber(Claim claim, SheetRepository sheets, SettingRepository settings,
            PeriodRepository periods) {
        LocalDate from = settings.periodNumberingFrom(claim.sheetId());
        if (from == null || sheets.today(claim.sheetId()).isBefore(from)) {
            return String.valueOf(sheets.nextClaimNumber(claim.sheetId()));
        }
        Period period = periods.findAll(claim.sheetId()).stream().filter((p) -> p.contains(claim.date())).findFirst()
                .orElse(null);
        String prefix = period == null ? "X" : period.name();
        String key = period == null ? "" : period.name().toLowerCase();
        return prefix + "-" + sheets.nextPeriodClaimNumber(claim.sheetId(), key);
    }

    private static BigDecimal settledDue(Claim claim, SheetRepository sheets, PersonRepository people,
            RateRepository rates, SettingRepository settings, ClaimRepository claims) {
        return ClaimDueNow.of(claim, sheets, people, rates, settings, claims);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Refuses (400) a re-date unless a steward re-dates an OPEN or PENDING claim to a date neither after its person's
 * retirement date nor inside a closed period; publishes the re-date.
 */
public class CheckClaimRedate {
    public void check(@RequestParam("user") String user, @Val Claim claim, @Val NewClaimDate newDate,
            SettingRepository settings, PersonRepository people, PeriodRepository periods, Out<Redating> redating)
            throws InvalidClaimException {
        LocalDate date = newDate.value();
        if (settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
            throw new InvalidClaimException("Only a steward can re-date a claim.");
        }
        if (!claim.status().open()) {
            throw new InvalidClaimException("A " + claim.status() + " claim cannot be re-dated.");
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        if (person != null && person.retiredBefore(date)) {
            throw new InvalidClaimException(
                    person.name() + " is retired from " + person.retiredFrom() + ": no claim can be dated " + date + ".");
        }
        Period closed = periods.closedOn(claim.sheetId(), date);
        if (closed != null) {
            throw new InvalidClaimException("The date " + date + " is in the closed period " + closed.name() + ".");
        }
        redating.set(new Redating(claim.date(), date));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.Objects;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Moves the claim to its new date, keeping its due-by and any statement figure. Under period numbering, a claim whose
 * period changes takes the next number of its new period's sequence (its old number is never used again).
 */
public class RedateClaim {
    public void redate(@Val Claim claim, @Val Redating redating, SheetRepository sheets, SettingRepository settings,
            PeriodRepository periods, ClaimRepository repository, Out<Claim> redated) {
        Claim moved = claim.redateTo(redating.to(), claim.number());
        LocalDate from = settings.periodNumberingFrom(claim.sheetId());
        boolean numbering = from != null && !sheets.today(claim.sheetId()).isBefore(from);
        if (numbering && claim.number() != null
                && !Objects.equals(periodOf(claim, redating.from(), periods), periodOf(claim, redating.to(), periods))) {
            moved = claim.redateTo(redating.to(), ApplyClaimAction.nextNumber(moved, sheets, settings, periods));
        }
        repository.redate(moved);
        redated.set(moved);
    }

    /** The name of the period containing the date (null: none). */
    private static String periodOf(Claim claim, LocalDate date, PeriodRepository periods) {
        return periods.findAll(claim.sheetId()).stream().filter((p) -> p.contains(date)).map(Period::name)
                .findFirst().orElse(null);
    }
}

